#include <stdlib.h>
#include <ctype.h>

#define CWE_MAX_LENGTH 5
#define CWE_PREFIX "CWE-"
#define CWE_PREFIX_LENGTH 4

int main(int argc, char *argv[])
{
	char *cwe_list[CWE_MAX_LENGTH];
	int cwe_count = 0;
	char *line = NULL;
	size_t len = 0;
	ssize_t read;
	int i;

	while ((read = getline(&line, &len, stdin))!= -1) {
		if (cwe_count >= CWE_MAX_LENGTH) {
			printf("Too many CWEs\n");
			return 1;
		}

		if (strncmp(CWE_PREFIX, line, CWE_PREFIX_LENGTH)!= 0) {
			printf("Invalid CWE\n");
			return 1;
		}

		for (i = 0; i < strlen(line); i++) {
			if (!isdigit(line[i])) {
				printf("Invalid CWE\n");
				return 1;
			}
		}

		cwe_list[cwe_count] = line;
		cwe_count++;
	}

	if (cwe_count!= CWE_MAX_LENGTH) {
		printf("Not enough CWEs\n");
		return 1;
	}

	printf("[");
	for (i = 0; i < CWE_MAX_LENGTH; i++) {
		if (i!= 0)
			printf(", ");
		printf("\"%s\"", cwe_list[i]);
	}
	printf("]\n");

	return 0;
}
