	}

	printf("[");
	for (i = 0; i < cwe_count; i++) {
		printf("\"%s\"", cwe_list[i]);
		if (i < cwe_count - 1)
			printf(", ");
	}
	printf("]");

	for (i = 0; i < 5; i++) {
		free(cwe_list[i]);
	}

	return 0;
}
