import json
import re
import sys

from cwe_list import cwe_list

def get_cwe_list(code):
    cwe_list = []
    for cwe in cwe_list:
        if cwe in code:
            cwe_list.append(cwe)
    return cwe_list

def main():
    if len(sys.argv)!= 2:
        print("Usage: python3 cwe_finder.py <code>")
        sys.exit(1)

    code = sys.argv[1]
    cwe_list = get_cwe_list(code)
    print(json.dumps(cwe_list))

if __name__ == "__main__":
    main()
